window.products.push({"id":306717,"name":"Yair Emanuel Aluminum Trivet with Silver Oriental Hamsa","category":"homeandappliances","retail price":24.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/41VhuH3u+dL._AC_.jpg","description":"This Yair Emanuel Aluminum Trivet with Silver Oriental Hamsa is shaped like a large hand and is decorated with an intricate floral pattern. This wonderful Yair Emanuel Aluminum Trivet is shaped like the Hamsa symbol that is perceived to be a symbol of good luck and protection from spiritual and physical harm. The hand is decorated with a floral pattern including flowers such as irises and lilies. This Hamsa trivet also features a large flower in the center. This item is a perfect wedding gift idea for a Jewish Holiday such as Passover and Rosh HaShana or for a lifecycle event such as a wedding!","images":["https://m.media-amazon.com/images/I/41VhuH3u+dL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Yair Emanuel","source_asin":"B007MCJZ00","category_path":"Home & Kitchen"},"sku":"BM-306717","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B007MCJZ00","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B007MCJZ00","price_pending":true,"merchant_ready":false});
